import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  const group = new Group();
  const cleanupTasks = [];

  // 1. Core Visual Tokens from Spec
  const colors = {
    ink: new Color(config.intent?.visualSpec?.colors?.ink || '#16161d'),
    paper: new Color(config.intent?.visualSpec?.colors?.paper || '#e8ecf2'),
    accent: new Color(config.intent?.visualSpec?.colors?.accent || '#ff2a38'),
    surface: new Color(config.intent?.visualSpec?.colors?.surface || '#0b0b10')
  };

  // 2. Card Demensions (Aspect ratio based on 512:320 atlas region = 1.6)
  const cardWidth = 2.5;
  const cardHeight = 1.5625;
  const margin = 0.04;

  // 3. Machined Metal Backing Plate
  const backplateGeo = new PlaneGeometry(cardWidth + margin, cardHeight + margin);

  // Custom TSL Material representing "engineered gradient surface" with red signal accent edge
  const backplateMat = new MeshStandardNodeMaterial({
    roughness: 0.52,
    metalness: 0.55,
    flatShading: true
  });

  // Procedural Engineered Gradient with TSL
  const uvs = uv();
  const gradient = mix(
    vec3(colors.surface.r, colors.surface.g, colors.surface.b),
    vec3(colors.ink.r, colors.ink.g, colors.ink.b),
    uvs.y
  );

  // Highlight border effect matching accent color
  const borderMask = smoothstep(0.48, 0.5, uvs.x.sub(0.5).abs())
    .or(smoothstep(0.47, 0.5, uvs.y.sub(0.5).abs()));

  const finalColor = mix(gradient, vec3(colors.accent.r, colors.accent.g, colors.accent.b), borderMask.mul(0.65));
  backplateMat.colorNode = finalColor;

  const backplateMesh = new Mesh(backplateGeo, backplateMat);
  backplateMesh.castShadow = true;
  group.add(backplateMesh);

  // 4. Main Textured Plane (Foreground Card Content)
  const contentGeo = new PlaneGeometry(cardWidth, cardHeight);
  const contentMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.1,
    transparent: true
  });

  const contentMesh = new Mesh(contentGeo, contentMat);
  contentMesh.position.z = 0.01; // Avoid z-fighting
  group.add(contentMesh);

  // Load the texture safely using the runtime context
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    contentMat.map = tex;
    contentMat.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed to load card texture, using fallback color', err);
    contentMat.colorNode = vec3(colors.paper.r, colors.paper.g, colors.paper.b);
  });

  // 5. Local Studio Lighting to lift the machined surface (W-PCP §9 Product Shot)
  const localRimLight = new DirectionalLight(colors.accent, 0.82);
  localRimLight.position.set(3, 2, 2);
  group.add(localRimLight);

  const localKeyLight = new DirectionalLight(colors.paper, 0.6);
  localKeyLight.position.set(-3, -2, 1.5);
  group.add(localKeyLight);

  // 6. Apply Cinematic Primitives (Iterate config primitives safely if present)
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primInstance = ctx.primitives[primitive.name](group, primitive.params);
        if (primInstance && primInstance.cleanup) {
          cleanupTasks.push(() => primInstance.cleanup());
        }
      }
    });
  }

  // 7. Cleanup Hook
  group.userData = {
    cleanup() {
      cleanupTasks.forEach((task) => task());
      backplateGeo.dispose();
      backplateMat.dispose();
      contentGeo.dispose();
      contentMat.dispose();
      localRimLight.dispose();
      localKeyLight.dispose();
    }
  };

  return group;
}
